package glitch

import data.glitch_lib

credential_keywords := {
    "password", "passwd", "pwd", "secret", "token", "credential", "auth", "authentication",
    "private_key", "privatekey", "cert", "certificate", "key_pair", "pubkey", "ssh_key",
    "api_key", "apikey", "access_key", "secret_key", "encryption_key",
    "secret_access_key", "master_password", "admin_password", "root_password", "default_password"
}

is_credential_field(name) {
    lower_name := lower(name)
    contains(lower_name, credential_keywords[_])
}

is_hardcoded_string(value) {
    value.ir_type == "String"
    value.value != ""
    not starts_with_reference(value.value)
    is_suspicious_value(value.value)
}

starts_with_reference(s) {
    regex.match("^(var\\.|data\\.|\\$\\{)", s)
} else {
    regex.match("^(lookup|get_param|secrets_manager|vault|kms|azure_keyvault|file\\(|path\\.module)", s)
}

is_suspicious_value(s) {
    # Length check - suspicious if too short or reasonable length for a secret
    count(s) >= 4
} else {
    # Base64 pattern
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", s)
} else {
    # Hex pattern
    regex.match("^[0-9a-fA-F]{16,}$", s)
} else {
    # PEM key header
    regex.match("-----BEGIN", s)
} else {
    # URI with credentials
    regex.match("^[a-zA-Z]+://[^@]+@[^/]+", s)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes in atomic units
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_credential_field(attr.name)
    is_hardcoded_string(attr.value)
    not glitch_lib.has_variable_reference(attr.value)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be embedded directly in infrastructure definitions. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    is_credential_field(var.name)
    is_hardcoded_string(var.value)
    not glitch_lib.has_variable_reference(var.value)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be embedded directly in infrastructure definitions. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check nested values in hashes/arrays for credential fields
    atomic_units := glitch_lib.all_atomic_units(parent)
