package glitch

import data.glitch_lib

credential_patterns := {
    "password", "passwd", "pwd", "secret", "token", "credential", "auth",
    "private_key", "privatekey", "priv_key", "privkey",
    "cert", "certificate", "key", "ssh_key", "api_key", "apikey",
    "access_key", "secret_key", "encryption_key", "secret_access_key",
    "master_password", "admin_password", "root_password", "default_password",
    "sha512_password", "sha256_password", "_password", "pass"
}

is_credential_name(name) {
    lower_name := lower(name)
    pattern := credential_patterns[_]
    contains(lower_name, pattern)
}

is_hardcoded_secret(value) {
    value.ir_type == "String"
    value.value != ""
    not starts_with_reference(value.value)
    has_secret_characteristics(value.value)
}

starts_with_reference(s) {
    regex.match("^\\$\\{[^}]+\\}", s)
} else {
    regex.match("^[a-zA-Z_][a-zA-Z0-9_]*\\.", s)
} else {
    regex.match("^\\{\\{", s)
}

has_secret_characteristics(s) {
    count(s) >= 6
} else {
    regex.match("^[A-Za-z0-9+/][A-Za-z0-9+/]{19,}={0,2}$", s)
} else {
    regex.match("^[0-9a-fA-F]{16,}$", s)
} else {
    regex.match("-----BEGIN", s)
} else {
    regex.match("^\\$[0-9]\\$", s)
}

# Recursively find hardcoded credentials in nested structures
find_credentials_in_value(key_name, value) = creds {
    creds := {{"key": key_name, "value": value}} {
        is_credential_name(key_name)
        is_hardcoded_secret(value)
    }
} else = creds {
    creds := union({c | c := find_credentials_in_hash(value.value)[_]}) {
        value.ir_type == "Hash"
    }
} else = creds {
    creds := union({c | c := find_credentials_in_array(value.value)[_]}) {
        value.ir_type == "Array"
    }
} else = creds {
    creds := {}
}

find_credentials_in_hash(entries) = creds {
    creds := union({
        find_credentials_in_value(entry.key.value, entry.value)
        | entry := entries[_]
    })
}

find_credentials_in_array(items) = creds {
    creds := union({
        find_credentials_in_value("", item)
        | item := items[_]
    })
}

# Check all nodes recursively for credentials
find_all_credentials(node) = creds {
    creds := {{"key": n.name, "element": n} {
        walk(node, [_, n])
        n.ir_type == "Variable"
        cred := find_credentials_in_value(n.name, n.value)[_]
        cred.key == n.name
        cred.value == n.value
    }} union {{"key": n.name, "element": n} {
        walk(node, [_, n])
        n.ir_type == "Attribute"
        cred := find_credentials_in_value(n.name, n.value)[_]
        cred.key == n.name
        cred.value == n.value
    }} union {{"key": e.key.value, "element": e.value} {
        walk(node, [_, n])
        n.ir_type == "Hash"
        entry := n.value[_]
        cred := find_credentials_in_value(entry.key.value, entry.value)[_]
        cred.key == entry.key.value
        cred.value == entry.value
        e := entry
    }}
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    creds := find_all_credentials(parent)
    cred := creds[_]

    result := {
        "type": "sec_hard_secr",
        "element": cred.element,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be embedded directly in infrastructure definitions. (CWE-798)"
    }
}

