credential_keywords := {"password", "passwd", "pwd", "secret", "token", "credential", "creds", "auth", "private_key", "privatekey", "ssh_key", "cert", "certificate", "api_key", "apikey", "access_key", "secret_key", "encryption_key", "secret_access_key", "master_password", "admin_password", "root_password", "default_password", "truststore_password", "keystore_password", "sha512_password"}

is_credential_name(name) {
    lower_name := lower(name)
    kw := credential_keywords[_]
    contains(lower_name, kw)
}

is_reference(val) {
    val.ir_type == "VariableReference"
}

is_reference(val) {
    val.ir_type == "String"
    regex.match("^\\$\\{", val.value)
}

is_reference(val) {
    val.ir_type == "String"
    regex.match("^\\{\\{", val.value)
}

is_reference(val) {
    val.ir_type == "String"
    regex.match("^var\\.", val.value)
}

is_reference(val) {
    val.ir_type == "String"
    regex.match("^data\\.", val.value)
}

is_reference(val) {
    val.ir_type == "String"
    regex.match("^file\\(", val.value)
}

is_reference(val) {
    val.ir_type == "FunctionCall"
}

is_reference(val) {
    val.ir_type == "MethodCall"
}

is_safe_value_type(val) {
    val.ir_type == "BlockExpr"
}

is_safe_value_type(val) {
    val.ir_type == "Null"
}

is_safe_value_type(val) {
    val.ir_type == "Undef"
}

is_safe_value_type(val) {
    val.ir_type == "Boolean"
}

is_safe_value_type(val) {
    val.ir_type == "Integer"
}

is_safe_value_type(val) {
    val.ir_type == "Float"
}

is_common_placeholder(s) {
    v := lower(s)
    placeholders := {"", "changeme", "change_me", "placeholder", "example", "demo", "test", "sample", "insert", "here", "null", "none", "nil", "todo", "fixme", "xxx"}
    v == placeholders[_]
}

is_obvious_non_secret(s) {
    lower(s) == lower("password")
}

has_secret_characteristics(s) {
    count(s) >= 4
    not is_common_placeholder(s)
    not is_obvious_non_secret(s)
}

has_secret_characteristics(s) {
    regex.match("^[A-Za-z0-9+/]{16,}={0,2}$", s)
}

has_secret_characteristics(s) {
    regex.match("^[0-9a-fA-F]{16,}$", s)
}

has_secret_characteristics(s) {
    regex.match("-----BEGIN", s)
}

has_secret_characteristics(s) {
    regex.match("^\\$[0-9]\\$", s)
}

check_hardcoded_secret(val) {
    val.ir_type == "String"
    val.value != ""
    has_secret_characteristics(val.value)
}

collect_all_key_values(node, results) {
    node.ir_type == "Hash"
    entry := node.value[_]
    results := entry
}

collect_all_key_values(node, results) {
    node.ir_type == "Array"
    item := node.value[_]
    item.ir_type == "Hash"
    entry := item.value[_]
    results := entry
}

collect_all_key_values(node, results) {
    node.ir_type == "Variable"
    results := {"key": {"ir_type": "String", "value": node.name}, "value": node.value}
}

collect_all_key_values(node, results) {
    node.ir_type == "Attribute"
    results := {"key": {"ir_type": "String", "value": node.name}, "value": node.value}
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    walk(parent, [path, node])
    kv := collect_all_key_values(node, _)
    kv.key.ir_type == "String"
    is_credential_name(kv.key.value)
    not is_reference(kv.value)
    not is_safe_value_type(kv.value)
    check_hardcoded_secret(kv.value)
    result := {
        "type": "sec_hard_secr",
        "element": kv.value,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be embedded directly in infrastructure definitions. (CWE-798)"
    }
}

